-- Procedimiento para generar asientos de un vuelo
CREATE OR ALTER PROCEDURE sp_GenerarAsientos
    @VueloID INT,
    @CapPrimera INT,
    @CapEconomica INT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @i INT = 1;
    DECLARE @fila INT = 1;
    DECLARE @letra CHAR(1);
    DECLARE @letras TABLE (idx INT, letra CHAR(1));

    INSERT INTO @letras VALUES (1,'A'),(2,'B'),(3,'C'),(4,'D'),(5,'E'),(6,'F');

    -- Asientos Primera Clase
    WHILE @i <= @CapPrimera
    BEGIN
        DECLARE @letraIdx INT = ((@i - 1) % 4) + 1;
        DECLARE @filaP INT = ((@i - 1) / 4) + 1;
        DECLARE @letraP CHAR(1) = (SELECT letra FROM @letras WHERE idx = @letraIdx);

        INSERT INTO Asientos (VueloID, NumeroAsiento, Clase)
        VALUES (@VueloID, CAST(@filaP AS VARCHAR) + @letraP, 'Primera');
        SET @i = @i + 1;
    END

    -- Asientos Económica
    SET @i = 1;
    WHILE @i <= @CapEconomica
    BEGIN
        SET @letraIdx = ((@i - 1) % 6) + 1;
        DECLARE @filaE INT = ((@i - 1) / 6) + (@CapPrimera / 4) + 2;
        DECLARE @letraE CHAR(1) = (SELECT letra FROM @letras WHERE idx = @letraIdx);

        INSERT INTO Asientos (VueloID, NumeroAsiento, Clase)
        VALUES (@VueloID, CAST(@filaE AS VARCHAR) + @letraE, 'Economica');
        SET @i = @i + 1;
    END
END;
GO

