-- Vista útil para consultar vuelos
CREATE VIEW vw_VuelosDisponibles AS
SELECT
    v.VueloID,
    v.NumeroVuelo,
    a.Modelo                    AS Avion,
    orig.Ciudad + ' (' + orig.Codigo + ')' AS Origen,
    dest.Ciudad + ' (' + dest.Codigo + ')' AS Destino,
    v.FechaSalida,
    v.FechaLlegada,
    DATEDIFF(MINUTE, v.FechaSalida, v.FechaLlegada) AS DuracionMinutos,
    v.PrecioEconomico,
    v.PrecioPrimera,
    v.Estado,
    (SELECT COUNT(*) FROM Asientos s WHERE s.VueloID = v.VueloID AND s.Clase = 'Economica' AND s.Disponible = 1) AS AsientosEcoDisponibles,
    (SELECT COUNT(*) FROM Asientos s WHERE s.VueloID = v.VueloID AND s.Clase = 'Primera'   AND s.Disponible = 1) AS AsientosPriDisponibles
FROM Vuelos v
JOIN Aviones    a    ON v.AvionID   = a.AvionID
JOIN Aeropuertos orig ON v.OrigenID = orig.AeropuertoID
JOIN Aeropuertos dest ON v.DestinoID= dest.AeropuertoID
WHERE v.Estado NOT IN ('Cancelado','Aterrizado');
GO
