using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using FlightReservation.Models;

namespace FlightReservation.DataAccess
{
    public class VueloRepository
    {
        private readonly DatabaseConnection _db;

        public VueloRepository(DatabaseConnection db) => _db = db;

        // Buscar vuelos disponibles
        public List<Vuelo> BuscarVuelos(string ciudadOrigen, string ciudadDestino, DateTime fecha)
        {
            var vuelos = new List<Vuelo>();
            const string query = @"
                SELECT * FROM vw_VuelosDisponibles
                WHERE Origen LIKE @Origen
                  AND Destino LIKE @Destino
                  AND CAST(FechaSalida AS DATE) = @Fecha
                ORDER BY FechaSalida";

            using var conn = _db.GetConnection();
            using var cmd = new SqlCommand(query, conn);
            cmd.Parameters.AddWithValue("@Origen",  $"%{ciudadOrigen}%");
            cmd.Parameters.AddWithValue("@Destino", $"%{ciudadDestino}%");
            cmd.Parameters.AddWithValue("@Fecha",   fecha.Date);

            conn.Open();
            using var reader = cmd.ExecuteReader();
            while (reader.Read())
                vuelos.Add(MapVuelo(reader));

            return vuelos;
        }

        // Obtener todos los vuelos disponibles
        public List<Vuelo> ObtenerTodosVuelos()
        {
            var vuelos = new List<Vuelo>();
            const string query = @"
                SELECT * FROM vw_VuelosDisponibles
                ORDER BY FechaSalida";

            using var conn = _db.GetConnection();
            using var cmd  = new SqlCommand(query, conn);
            conn.Open();
            using var reader = cmd.ExecuteReader();
            while (reader.Read())
                vuelos.Add(MapVuelo(reader));

            return vuelos;
        }

        // Obtener vuelo por ID
        public Vuelo ObtenerVueloPorId(int vueloId)
        {
            const string query = "SELECT * FROM vw_VuelosDisponibles WHERE VueloID = @ID";
            using var conn = _db.GetConnection();
            using var cmd  = new SqlCommand(query, conn);
            cmd.Parameters.AddWithValue("@ID", vueloId);
            conn.Open();
            using var reader = cmd.ExecuteReader();
            return reader.Read() ? MapVuelo(reader) : null;
        }

        // Obtener asientos disponibles de un vuelo
        public List<Asiento> ObtenerAsientosDisponibles(int vueloId, string clase = null)
        {
            var asientos = new List<Asiento>();
            var query = @"
                SELECT * FROM Asientos
                WHERE VueloID = @VueloID AND Disponible = 1";

            if (!string.IsNullOrEmpty(clase))
                query += " AND Clase = @Clase";

            query += " ORDER BY NumeroAsiento";

            using var conn = _db.GetConnection();
            using var cmd  = new SqlCommand(query, conn);
            cmd.Parameters.AddWithValue("@VueloID", vueloId);
            if (!string.IsNullOrEmpty(clase))
                cmd.Parameters.AddWithValue("@Clase", clase);

            conn.Open();
            using var reader = cmd.ExecuteReader();
            while (reader.Read())
            {
                asientos.Add(new Asiento
                {
                    AsientoID     = (int)reader["AsientoID"],
                    VueloID       = (int)reader["VueloID"],
                    NumeroAsiento = reader["NumeroAsiento"].ToString(),
                    Clase         = reader["Clase"].ToString(),
                    Disponible    = (bool)reader["Disponible"]
                });
            }

            return asientos;
        }

        private static Vuelo MapVuelo(SqlDataReader r) => new Vuelo
        {
            VueloID                = (int)r["VueloID"],
            NumeroVuelo            = r["NumeroVuelo"].ToString(),
            Avion                  = r["Avion"].ToString(),
            Origen                 = r["Origen"].ToString(),
            Destino                = r["Destino"].ToString(),
            FechaSalida            = (DateTime)r["FechaSalida"],
            FechaLlegada           = (DateTime)r["FechaLlegada"],
            DuracionMinutos        = (int)r["DuracionMinutos"],
            PrecioEconomico        = (decimal)r["PrecioEconomico"],
            PrecioPrimera          = (decimal)r["PrecioPrimera"],
            Estado                 = r["Estado"].ToString(),
            AsientosEcoDisponibles = (int)r["AsientosEcoDisponibles"],
            AsientosPriDisponibles = (int)r["AsientosPriDisponibles"]
        };
    }
}
