// DataAccess/ReservaRepository.cs
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using FlightReservation.Models;

namespace FlightReservation.DataAccess
{
    public class ReservaRepository
    {
        private readonly DatabaseConnection _db;

        public ReservaRepository(DatabaseConnection db) => _db = db;

        public string CrearReserva(Reserva reserva)
        {
            using var conn = _db.GetConnection();
            conn.Open();
            using var transaction = conn.BeginTransaction();

            try
            {
                // 1. Verificar disponibilidad del asiento
                const string checkQuery = @"
                    SELECT Disponible FROM Asientos
                    WHERE AsientoID = @AsientoID";

                using (var checkCmd = new SqlCommand(checkQuery, conn, transaction))
                {
                    checkCmd.Parameters.AddWithValue("@AsientoID", reserva.AsientoID);
                    var disponible = (bool)checkCmd.ExecuteScalar();
                    if (!disponible)
                        throw new InvalidOperationException("El asiento ya no está disponible.");
                }

                // 2. Generar código de reserva
                var codigo = GenerarCodigo();
                reserva.CodigoReserva = codigo;

                // 3. Insertar reserva
                const string insertQuery = @"
                    INSERT INTO Reservas
                        (CodigoReserva, PasajeroID, VueloID, AsientoID,
                         Estado, MontoTotal, MetodoPago, Observaciones)
                    VALUES
                        (@Codigo, @PasajeroID, @VueloID, @AsientoID,
                         'Confirmada', @Monto, @Pago, @Obs);
                    SELECT SCOPE_IDENTITY();";

                using (var insertCmd = new SqlCommand(insertQuery, conn, transaction))
                {
                    insertCmd.Parameters.AddWithValue("@Codigo",     codigo);
                    insertCmd.Parameters.AddWithValue("@PasajeroID", reserva.PasajeroID);
                    insertCmd.Parameters.AddWithValue("@VueloID",    reserva.VueloID);
                    insertCmd.Parameters.AddWithValue("@AsientoID",  reserva.AsientoID);
                    insertCmd.Parameters.AddWithValue("@Monto",      reserva.MontoTotal);
                    insertCmd.Parameters.AddWithValue("@Pago",       reserva.MetodoPago);
                    insertCmd.Parameters.AddWithValue("@Obs",
                        reserva.Observaciones ?? (object)DBNull.Value);

                    reserva.ReservaID = Convert.ToInt32(insertCmd.ExecuteScalar());
                }

                // 4. Marcar asiento como no disponible
                const string updateAsiento = @"
                    UPDATE Asientos SET Disponible = 0
                    WHERE AsientoID = @AsientoID";

                using (var updCmd = new SqlCommand(updateAsiento, conn, transaction))
                {
                    updCmd.Parameters.AddWithValue("@AsientoID", reserva.AsientoID);
                    updCmd.ExecuteNonQuery();
                }

                // 5. Registrar historial
                const string historial = @"
                    INSERT INTO HistorialReservas (ReservaID, EstadoAnterior, EstadoNuevo, UsuarioCambio)
                    VALUES (@ID, NULL, 'Confirmada', 'Sistema')";

                using (var histCmd = new SqlCommand(historial, conn, transaction))
                {
                    histCmd.Parameters.AddWithValue("@ID", reserva.ReservaID);
                    histCmd.ExecuteNonQuery();
                }

                transaction.Commit();
                return codigo;
            }
            catch
            {
                transaction.Rollback();
                throw;
            }
        }

        public bool CancelarReserva(string codigoReserva, string motivo = null)
        {
            using var conn = _db.GetConnection();
            conn.Open();
            using var transaction = conn.BeginTransaction();

            try
            {
                // Obtener datos de la reserva
                const string selectQuery = @"
                    SELECT ReservaID, AsientoID, Estado
                    FROM Reservas WHERE CodigoReserva = @Codigo";

                int reservaId, asientoId;
                string estadoActual;

                using (var cmd = new SqlCommand(selectQuery, conn, transaction))
                {
                    cmd.Parameters.AddWithValue("@Codigo", codigoReserva);
                    using var reader = cmd.ExecuteReader();
                    if (!reader.Read()) return false;
                    reservaId    = (int)reader["ReservaID"];
                    asientoId    = (int)reader["AsientoID"];
                    estadoActual = reader["Estado"].ToString();
                }

                if (estadoActual == "Cancelada")
                    throw new InvalidOperationException("La reserva ya está cancelada.");

                // Cancelar reserva
                const string cancelQuery = @"
                    UPDATE Reservas
                    SET Estado = 'Cancelada',
                        Observaciones = ISNULL(Observaciones,'') + ' | Cancelación: ' + @Motivo
                    WHERE ReservaID = @ID";

                using (var cmd = new SqlCommand(cancelQuery, conn, transaction))
                {
                    cmd.Parameters.AddWithValue("@ID",     reservaId);
                    cmd.Parameters.AddWithValue("@Motivo", motivo ?? "Sin motivo");
                    cmd.ExecuteNonQuery();
                }

                // Liberar asiento
                const string liberarQuery = @"
                    UPDATE Asientos SET Disponible = 1 WHERE AsientoID = @AsientoID";

                using (var cmd = new SqlCommand(liberarQuery, conn, transaction))
                {
                    cmd.Parameters.AddWithValue("@AsientoID", asientoId);
                    cmd.ExecuteNonQuery();
                }

                // Historial
                const string historial = @"
                    INSERT INTO HistorialReservas (ReservaID, EstadoAnterior, EstadoNuevo, UsuarioCambio)
                    VALUES (@ID, @Anterior, 'Cancelada', 'Sistema')";

                using (var cmd = new SqlCommand(historial, conn, transaction))
                {
                    cmd.Parameters.AddWithValue("@ID",       reservaId);
                    cmd.Parameters.AddWithValue("@Anterior", estadoActual);
                    cmd.ExecuteNonQuery();
                }

                transaction.Commit();
                return true;
            }
            catch
            {
                transaction.Rollback();
                throw;
            }
        }

        public Reserva ConsultarReserva(string codigoReserva)
        {
            const string query = @"
                SELECT
                    r.ReservaID, r.CodigoReserva, r.PasajeroID, r.VueloID,
                    r.AsientoID, r.FechaReserva, r.Estado, r.MontoTotal,
                    r.MetodoPago, r.Observaciones,
                    p.Nombres + ' ' + p.Apellidos  AS NombrePasajero,
                    v.NumeroVuelo,
                    ao.Ciudad + ' (' + ao.Codigo + ')' AS Origen,
                    ad.Ciudad + ' (' + ad.Codigo + ')' AS Destino,
                    v.FechaSalida,
                    a.NumeroAsiento, a.Clase
                FROM Reservas r
                JOIN Pasajeros p    ON r.PasajeroID = p.PasajeroID
                JOIN Vuelos    v    ON r.VueloID    = v.VueloID
                JOIN Aeropuertos ao ON v.OrigenID   = ao.AeropuertoID
                JOIN Aeropuertos ad ON v.DestinoID  = ad.AeropuertoID
                JOIN Asientos    a  ON r.AsientoID  = a.AsientoID
                WHERE r.CodigoReserva = @Codigo";

            using var conn = _db.GetConnection();
            using var cmd  = new SqlCommand(query, conn);
            cmd.Parameters.AddWithValue("@Codigo", codigoReserva);
            conn.Open();
            using var reader = cmd.ExecuteReader();

            if (!reader.Read()) return null;

            return new Reserva
            {
                ReservaID      = (int)reader["ReservaID"],
                CodigoReserva  = reader["CodigoReserva"].ToString(),
                PasajeroID     = (int)reader["PasajeroID"],
                VueloID        = (int)reader["VueloID"],
                AsientoID      = (int)reader["AsientoID"],
                FechaReserva   = (DateTime)reader["FechaReserva"],
                Estado         = reader["Estado"].ToString(),
                MontoTotal     = (decimal)reader["MontoTotal"],
                MetodoPago     = reader["MetodoPago"].ToString(),
                Observaciones  = reader["Observaciones"] == DBNull.Value
                                    ? null : reader["Observaciones"].ToString(),
                NombrePasajero = reader["NombrePasajero"].ToString(),
                NumeroVuelo    = reader["NumeroVuelo"].ToString(),
                Origen         = reader["Origen"].ToString(),
                Destino        = reader["Destino"].ToString(),
                FechaSalida    = (DateTime)reader["FechaSalida"],
                NumeroAsiento  = reader["NumeroAsiento"].ToString(),
                Clase          = reader["Clase"].ToString()
            };
        }

        public List<Reserva> ObtenerReservasPorPasajero(string numDocumento)
        {
            var reservas = new List<Reserva>();
            const string query = @"
                SELECT r.CodigoReserva, v.NumeroVuelo,
                       ao.Ciudad AS Origen, ad.Ciudad AS Destino,
                       v.FechaSalida, a.NumeroAsiento, a.Clase,
                       r.Estado, r.MontoTotal, r.FechaReserva
                FROM Reservas r
                JOIN Pasajeros   p  ON r.PasajeroID = p.PasajeroID
                JOIN Vuelos      v  ON r.VueloID    = v.VueloID
                JOIN Aeropuertos ao ON v.OrigenID   = ao.AeropuertoID
                JOIN Aeropuertos ad ON v.DestinoID  = ad.AeropuertoID
                JOIN Asientos    a  ON r.AsientoID  = a.AsientoID
                WHERE p.NumeroDocumento = @NumDoc
                ORDER BY r.FechaReserva DESC";

            using var conn = _db.GetConnection();
            using var cmd  = new SqlCommand(query, conn);
            cmd.Parameters.AddWithValue("@NumDoc", numDocumento);
            conn.Open();
            using var reader = cmd.ExecuteReader();
            while (reader.Read())
            {
                reservas.Add(new Reserva
                {
                    CodigoReserva = reader["CodigoReserva"].ToString(),
                    NumeroVuelo   = reader["NumeroVuelo"].ToString(),
                    Origen        = reader["Origen"].ToString(),
                    Destino       = reader["Destino"].ToString(),
                    FechaSalida   = (DateTime)reader["FechaSalida"],
                    NumeroAsiento = reader["NumeroAsiento"].ToString(),
                    Clase         = reader["Clase"].ToString(),
                    Estado        = reader["Estado"].ToString(),
                    MontoTotal    = (decimal)reader["MontoTotal"],
                    FechaReserva  = (DateTime)reader["FechaReserva"]
                });
            }

            return reservas;
        }

        private static string GenerarCodigo()
        {
            var chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
            var rnd   = new Random();
            var code  = new char[8];
            for (int i = 0; i < 8; i++)
                code[i] = chars[rnd.Next(chars.Length)];
            return new string(code);
        }
    }
}
