// Services/ReservaService.cs
using System;
using System.Collections.Generic;
using FlightReservation.DataAccess;
using FlightReservation.Models;

namespace FlightReservation.Services
{
    public class ReservaService
    {
        private readonly VueloRepository    _vueloRepo;
        private readonly PasajeroRepository _pasajeroRepo;
        private readonly ReservaRepository  _reservaRepo;

        public ReservaService(DatabaseConnection db)
        {
            _vueloRepo    = new VueloRepository(db);
            _pasajeroRepo = new PasajeroRepository(db);
            _reservaRepo  = new ReservaRepository(db);
        }

        public List<Vuelo> BuscarVuelos(
            string ciudadOrigen, string ciudadDestino, DateTime fecha)
            => _vueloRepo.BuscarVuelos(ciudadOrigen, ciudadDestino, fecha);

        public List<Vuelo> ObtenerTodosVuelos()
            => _vueloRepo.ObtenerTodosVuelos();

        public List<Asiento> ObtenerAsientos(int vueloId, string clase = null)
            => _vueloRepo.ObtenerAsientosDisponibles(vueloId, clase);

        public Pasajero ObtenerORegistrarPasajero(Pasajero pasajero)
        {
            var existente = _pasajeroRepo
                .BuscarPorDocumento(pasajero.TipoDocumento, pasajero.NumeroDocumento);

            if (existente != null) return existente;

            pasajero.PasajeroID = _pasajeroRepo.Registrar(pasajero);
            return pasajero;
        }

        public (bool exito, string codigo, string mensaje) CrearReserva(
            int vueloId, int asientoId, Pasajero pasajero, string metodoPago)
        {
            try
            {
                // Validar vuelo
                var vuelo = _vueloRepo.ObtenerVueloPorId(vueloId);
                if (vuelo == null)
                    return (false, null, "Vuelo no encontrado.");

                if (vuelo.FechaSalida < DateTime.Now)
                    return (false, null, "No se puede reservar un vuelo ya salido.");

                // Obtener/registrar pasajero
                pasajero = ObtenerORegistrarPasajero(pasajero);

                // Obtener asiento y precio
                var asientos = _vueloRepo.ObtenerAsientosDisponibles(vueloId);
                var asiento  = asientos.Find(a => a.AsientoID == asientoId);

                if (asiento == null || !asiento.Disponible)
                    return (false, null, "El asiento seleccionado no está disponible.");

                var precio = asiento.Clase == "Primera"
                    ? vuelo.PrecioPrimera : vuelo.PrecioEconomico;

                var reserva = new Reserva
                {
                    PasajeroID  = pasajero.PasajeroID,
                    VueloID     = vueloId,
                    AsientoID   = asientoId,
                    MontoTotal  = precio,
                    MetodoPago  = metodoPago
                };

                var codigo = _reservaRepo.CrearReserva(reserva);
                return (true, codigo, $"✅ Reserva creada exitosamente. Código: {codigo}");
            }
            catch (Exception ex)
            {
                return (false, null, $"Error al crear reserva: {ex.Message}");
            }
        }

        public Reserva ConsultarReserva(string codigo)
            => _reservaRepo.ConsultarReserva(codigo);

        public List<Reserva> MisReservas(string numDocumento)
            => _reservaRepo.ObtenerReservasPorPasajero(numDocumento);

        public (bool exito, string mensaje) CancelarReserva(string codigo, string motivo)
        {
            try
            {
                var resultado = _reservaRepo.CancelarReserva(codigo, motivo);
                return resultado
                    ? (true,  "✅ Reserva cancelada exitosamente.")
                    : (false, "❌ No se encontró la reserva.");
            }
            catch (Exception ex)
            {
                return (false, $"Error: {ex.Message}");
            }
        }
    }
}
