# Task Pool Implementation in TypeScript

## Implementation

```typescript
type Task<T> = () => Promise<T>;

interface TaskPoolOptions {
  concurrency: number;
}

class TaskPool {
  private concurrency: number;
  private running: number = 0;
  private queue: Array<{
    task: Task<unknown>;
    resolve: (value: unknown) => void;
    reject: (reason?: unknown) => void;
  }> = [];

  constructor({ concurrency }: TaskPoolOptions) {
    if (concurrency < 1) {
      throw new Error("Concurrency must be at least 1");
    }
    this.concurrency = concurrency;
  }

  /**
   * Add a task to the pool.
   * The task will run immediately if concurrency limit is not reached,
   * otherwise it will be queued.
   */
  add<T>(task: Task<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.queue.push({
        task: task as Task<unknown>,
        resolve: resolve as (value: unknown) => void,
        reject,
      });
      this.run();
    });
  }

  /**
   * Add multiple tasks and wait for all to complete.
   */
  addAll<T>(tasks: Task<T>[]): Promise<T[]> {
    return Promise.all(tasks.map((task) => this.add(task)));
  }

  /**
   * Wait for all queued and running tasks to complete.
   */
  drain(): Promise<void> {
    if (this.running === 0 && this.queue.length === 0) {
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      const check = () => {
        if (this.running === 0 && this.queue.length === 0) {
          resolve();
        }
      };
      // Poll every 50ms (or use event-based approach)
      const interval = setInterval(() => {
        check();
        if (this.running === 0 && this.queue.length === 0) {
          clearInterval(interval);
        }
      }, 50);
    });
  }

  get stats() {
    return {
      running: this.running,
      queued: this.queue.length,
      concurrency: this.concurrency,
    };
  }

  private run(): void {
    while (this.running < this.concurrency && this.queue.length > 0) {
      const item = this.queue.shift()!;
      this.running++;

      item
        .task()
        .then((result) => {
          item.resolve(result);
        })
        .catch((error) => {
          item.reject(error);
        })
        .finally(() => {
          this.running--;
          this.run(); // pick up next task from queue
        });
    }
  }
}
```

