## Usage Examples

```typescript
// ─── Helper ──────────────────────────────────────────────────────────────────
const delay = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

const createTask = (id: number, duration: number): Task<string> => {
  return async () => {
    console.log(`  [${new Date().toISOString()}] Task ${id} STARTED`);
    await delay(duration);
    console.log(`  [${new Date().toISOString()}] Task ${id} FINISHED`);
    return `Result of task ${id}`;
  };
};

// ─── Example 1: Basic concurrency limit ──────────────────────────────────────
async function example1() {
  console.log("\n=== Example 1: Concurrency limit of 2 ===");

  const pool = new TaskPool({ concurrency: 2 });

  const tasks = [
    createTask(1, 1000),
    createTask(2, 500),
    createTask(3, 800),
    createTask(4, 300),
    createTask(5, 600),
  ];

  const results = await pool.addAll(tasks);
  console.log("All results:", results);
}

// ─── Example 2: Adding tasks dynamically ─────────────────────────────────────
async function example2() {
  console.log("\n=== Example 2: Dynamic task addition ===");

  const pool = new TaskPool({ concurrency: 3 });

  // Add tasks one by one
  pool.add(createTask(1, 1000)).then((r) => console.log("Got:", r));
  pool.add(createTask(2, 500)).then((r) => console.log("Got:", r));
  pool.add(createTask(3, 800)).then((r) => console.log("Got:", r));

  // Add more after a delay
  await delay(200);
  console.log("Stats after 200ms:", pool.stats);

  pool.add(createTask(4, 300)).then((r) => console.log("Got:", r));
  pool.add(createTask(5, 600)).then((r) => console.log("Got:", r));

  await pool.drain();
  console.log("All tasks drained!");
}

// ─── Example 3: Error handling ───────────────────────────────────────────────
async function example3() {
  console.log("\n=== Example 3: Error handling ===");

  const pool = new TaskPool({ concurrency: 2 });

  const results = await Promise.allSettled([
    pool.add(async () => {
      await delay(300);
      return "success 1";
    }),
    pool.add(async () => {
      await delay(100);
      throw new Error("Task failed!");
    }),
    pool.add(async () => {
      await delay(200);
      return "success 3";
    }),
  ]);

  results.forEach((result, index) => {
    if (result.status === "fulfilled") {
      console.log(`Task ${index + 1}: ✅`, result.value);
    } else {
      console.log(`Task ${index + 1}: ❌`, result.reason.message);
    }
  });
}

// ─── Run all examples ─────────────────────────────────────────────────────────
(async () => {
  await example1();
  await example2();
  await example3();
})();
```

